import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<Video> corpus = Arrays.asList(
            new Video("V1", Arrays.asList("dance", "music"), 0.8),
            new Video("V2", Arrays.asList("comedy"), 0.9),
            new Video("V3", Arrays.asList("dance"), 0.6),
            new Video("V4", Arrays.asList("cooking"), 0.95), // highest raw score, but not relevant to this viewer
            new Video("V5", Arrays.asList("music"), 0.7)
        );

        UserProfile user = new UserProfile("user-U", new HashSet<>(Arrays.asList("dance", "music")));
        RecommendationService recommender = new RecommendationService();

        // First feed request: expect V1 and V5 (highest scores among relevant candidates), never V4.
        List<Video> firstFeed = recommender.getForYouFeed(user, corpus, 2);
        System.out.println("First feed batch:");
        for (Video v : firstFeed) System.out.println("  " + v.videoId + " (score " + v.predictedCompletionScore + ")");

        // Second feed request in the same session: V1 and V5 already shown, so only V3 remains relevant.
        List<Video> secondFeed = recommender.getForYouFeed(user, corpus, 2);
        System.out.println("Second feed batch (should exclude already shown videos):");
        for (Video v : secondFeed) System.out.println("  " + v.videoId + " (score " + v.predictedCompletionScore + ")");
    }
}

// One video: its id, content tags, and a precomputed predicted completion
// score standing in for what a real ranking model would compute.
class Video {
    String videoId;
    List<String> tags;
    double predictedCompletionScore;

    Video(String videoId, List<String> tags, double predictedCompletionScore) {
        this.videoId = videoId;
        this.tags = tags;
        this.predictedCompletionScore = predictedCompletionScore;
    }
}

// A viewer's current interest tags and which videos have already been shown
// to them in this session, for de-duplication.
class UserProfile {
    String userId;
    Set<String> interestTags;
    Set<String> alreadyShownVideoIds = new HashSet<>();

    UserProfile(String userId, Set<String> interestTags) {
        this.userId = userId;
        this.interestTags = interestTags;
    }
}

// Implements the two-stage retrieve-then-rank pipeline: candidate generation
// narrows the corpus by relevance and session history, then ranking orders
// the much smaller candidate set by predicted completion score.
class RecommendationService {
    // Candidate generation: keep only videos matching at least one of this
    // viewer's interest tags, and not already shown this session. A video's
    // raw score is irrelevant at this stage; relevance is checked first.
    List<Video> candidateGenerate(UserProfile user, List<Video> corpus) {
        List<Video> candidates = new ArrayList<>();
        for (Video video : corpus) {
            if (user.alreadyShownVideoIds.contains(video.videoId)) continue; // session de-duplication
            boolean matchesInterest = false;
            for (String tag : video.tags) {
                if (user.interestTags.contains(tag)) { matchesInterest = true; break; }
            }
            if (matchesInterest) candidates.add(video);
        }
        return candidates;
    }

    // Ranking: order the (much smaller) candidate set by predicted completion score.
    List<Video> rank(List<Video> candidates) {
        List<Video> ranked = new ArrayList<>(candidates);
        ranked.sort((a, b) -> Double.compare(b.predictedCompletionScore, a.predictedCompletionScore));
        return ranked;
    }

    List<Video> getForYouFeed(UserProfile user, List<Video> corpus, int feedSize) {
        List<Video> candidates = candidateGenerate(user, corpus);
        List<Video> ranked = rank(candidates);
        List<Video> feed = ranked.size() > feedSize ? ranked.subList(0, feedSize) : ranked;
        for (Video video : feed) {
            user.alreadyShownVideoIds.add(video.videoId); // mark as shown for future session de-duplication
        }
        return feed;
    }
}

