    # shown to them in this session, for de-duplication.
    def __init__(self, user_id, interest_tags):
        self.user_id = user_id
        self.interest_tags = interest_tags
        self.already_shown_video_ids = set()


class RecommendationService:
    # Implements the two-stage retrieve-then-rank pipeline: candidate generation
    # narrows the corpus by relevance and session history, then ranking orders
    # the much smaller candidate set by predicted completion score.
    def candidate_generate(self, user, corpus):
        candidates = []
        for video in corpus:
            if video.video_id in user.already_shown_video_ids:
                continue  # session de-duplication
            if any(tag in user.interest_tags for tag in video.tags):
                candidates.append(video)
        return candidates

    def rank(self, candidates):
        return sorted(candidates, key=lambda v: v.predicted_completion_score, reverse=True)

    def get_for_you_feed(self, user, corpus, feed_size):
        candidates = self.candidate_generate(user, corpus)
        ranked = self.rank(candidates)
        feed = ranked[:feed_size]
        for video in feed:
            user.already_shown_video_ids.add(video.video_id)  # mark as shown for future session de-duplication
        return feed


def main():
    corpus = [
        Video("V1", ["dance", "music"], 0.8),
        Video("V2", ["comedy"], 0.9),
        Video("V3", ["dance"], 0.6),
        Video("V4", ["cooking"], 0.95),  # highest raw score, but not relevant to this viewer
        Video("V5", ["music"], 0.7),
    ]

    user = UserProfile("user-U", {"dance", "music"})
    recommender = RecommendationService()

    # First feed request: expect V1 and V5 (highest scores among relevant candidates), never V4.
    first_feed = recommender.get_for_you_feed(user, corpus, 2)
    print("First feed batch:")
    for v in first_feed:
        print(f"  {v.video_id} (score {v.predicted_completion_score})")

    # Second feed request in the same session: V1 and V5 already shown, so only V3 remains relevant.
    second_feed = recommender.get_for_you_feed(user, corpus, 2)
    print("Second feed batch (should exclude already shown videos):")
    for v in second_feed:
        print(f"  {v.video_id} (score {v.predicted_completion_score})")


if __name__ == "__main__":
    main()

