#include <iostream>
#include <vector>
#include <set>
#include <string>
#include <algorithm>
using namespace std;

// One video: its id, content tags, and a precomputed predicted completion
// score standing in for what a real ranking model would compute.
struct Video {
    string videoId;
    vector<string> tags;
    double predictedCompletionScore;
};

// A viewer's current interest tags and which videos have already been shown
// to them in this session, for de-duplication.
struct UserProfile {
    string userId;
    set<string> interestTags;
    set<string> alreadyShownVideoIds;
};

// Implements the two-stage retrieve-then-rank pipeline: candidate generation
// narrows the corpus by relevance and session history, then ranking orders
// the much smaller candidate set by predicted completion score.
class RecommendationService {
public:
    vector<Video> candidateGenerate(const UserProfile& user, const vector<Video>& corpus) {
        vector<Video> candidates;
        for (const auto& video : corpus) {
            if (user.alreadyShownVideoIds.count(video.videoId)) continue; // session de-duplication
            bool matchesInterest = false;
            for (const auto& tag : video.tags) {
                if (user.interestTags.count(tag)) { matchesInterest = true; break; }
            }
            if (matchesInterest) candidates.push_back(video);
        }
        return candidates;
    }

    vector<Video> rank(vector<Video> candidates) {
        sort(candidates.begin(), candidates.end(), [](const Video& a, const Video& b) {
            return a.predictedCompletionScore > b.predictedCompletionScore;
        });
        return candidates;
    }

    vector<Video> getForYouFeed(UserProfile& user, const vector<Video>& corpus, int feedSize) {
        vector<Video> candidates = candidateGenerate(user, corpus);
        vector<Video> ranked = rank(candidates);
        vector<Video> feed(ranked.begin(), ranked.begin() + min((size_t)feedSize, ranked.size()));
        for (const auto& video : feed) {
            user.alreadyShownVideoIds.insert(video.videoId); // mark as shown for future session de-duplication
        }
        return feed;
    }
};

int main() {
    vector<Video> corpus = {
        {"V1", {"dance", "music"}, 0.8},
        {"V2", {"comedy"}, 0.9},
        {"V3", {"dance"}, 0.6},
        {"V4", {"cooking"}, 0.95}, // highest raw score, but not relevant to this viewer
        {"V5", {"music"}, 0.7}
    };

    UserProfile user{"user-U", {"dance", "music"}, {}};
    RecommendationService recommender;

    // First feed request: expect V1 and V5 (highest scores among relevant candidates), never V4.
    vector<Video> firstFeed = recommender.getForYouFeed(user, corpus, 2);
    cout << "First feed batch:" << endl;
    for (const auto& v : firstFeed) cout << "  " << v.videoId << " (score " << v.predictedCompletionScore << ")" << endl;

    // Second feed request in the same session: V1 and V5 already shown, so only V3 remains relevant.
    vector<Video> secondFeed = recommender.getForYouFeed(user, corpus, 2);
    cout << "Second feed batch (should exclude already shown videos):" << endl;
    for (const auto& v : secondFeed) cout << "  " << v.videoId << " (score " << v.predictedCompletionScore << ")" << endl;

    return 0;
}

